'use server'

import { revalidatePath } from 'next/cache'
import fs from 'fs/promises'
import path from 'path'

const PREF_FILE = path.resolve('preference.json')

export async function toggleNotifications() {
  try {
    // Read current preference
    const data = await fs.readFile(PREF_FILE, 'utf8')
    const pref = JSON.parse(data)

    // Toggle value
    const newPref = { ...pref, notifications: !pref.notifications }

    // Write back
    await fs.writeFile(PREF_FILE, JSON.stringify(newPref, null, 2))

    // Refresh the page
    revalidatePath('/')

    return { success: true, notifications: newPref.notifications }
  } catch (error) {
    console.error('Failed to toggle notifications:', error)
    return { success: false, error: 'Failed to update preference' }
  }
}

