          <p>
            Current Notification Status:&nbsp;
            <code className="font-mono font-bold text-green-500">
              {notificationsEnabled ? 'ON' : 'OFF'}
            </code>
          </p>
        </div>
      </div>

      <div className="mt-32">
        <form action={toggleNotifications}>
          <button
            type="submit"
            className={`px-4 py-2 font-bold text-white rounded transition-colors ${
